//! Complete original appearance DATA over existing field-index and selected schema loans.
use crate::{captured_api_pages as shared,captured_generator_budget::Budget,captured_raw_file::Config,captured_reactive_reads::Failure,reactive_raw_policy_pages::RawPolicyPages,sys_appearance_policy as policy,lint::{Site,AllowUse}};
use std::{collections::HashSet,io,sync::Arc};
pub fn metadata()->&'static crate::lint::Meta{static META:std::sync::OnceLock<crate::lint::Meta>=std::sync::OnceLock::new();META.get_or_init(||crate::dm::sys::module_metadata(&crate::dm::sys::SysModule{name:crate::allow_registry_fields::sys_appearance::SCOPE_MODULE_NAME,rules:policy::RULES,allow_extra:crate::allow_registry_fields::sys_appearance::ALLOW_EXTRA,allow_extra_rules:&["update_icon_override"],..crate::dm::sys::SysModule::DEFAULT},crate::lint::ScanKind::Tree))}
pub struct AppearanceData{data:shared::ApiData}
impl AppearanceData{pub fn sites(&self)->&[Site]{self.data.sites()}pub fn source_text(&self)->&[String]{self.data.source_text()}pub fn allow_used(&self)->&[AllowUse]{self.data.allow_used()}pub fn allow_source_digest(&self,rel:&str)->Option<&[u8;20]>{self.data.allow_source_digest(rel)}}
fn fund(b:&Budget,bytes:Option<usize>)->Result<(),Failure>{let Some(bytes)=bytes else{b.deny();return Err(Failure::Operational(io::ErrorKind::OutOfMemory.into()))};b.charge(bytes).map_err(|message|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))}
fn regs_bound(rows:&[policy::RegFact])->Option<usize>{let mut bytes=rows.len().checked_mul(4*std::mem::size_of::<policy::RegFact>())?.checked_add(128)?;for(name,owner,field,_)in rows{bytes=bytes.checked_add(name.len().checked_add(owner.len())?.checked_add(field.len())?.checked_mul(4)?)?.checked_add(3072)?;}Some(bytes)}
fn events_bound(rows:&[policy::WatchEvent])->Option<usize>{let mut bytes=rows.len().checked_mul(4*std::mem::size_of::<policy::WatchEvent>())?.checked_add(128)?;for(kind,owner,text)in rows{bytes=bytes.checked_add(kind.len().checked_add(owner.len())?.checked_add(text.len())?.checked_mul(4)?)?.checked_add(4096)?;}Some(bytes)}
pub fn collect(pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<AppearanceData,Failure>{shared::with_field_index(pages,root,poll,|index,b|{let selected=|relative:&str|!config.policy_path_exempt("sys/appearance","sys",relative);let mut schema=Vec::new();if !pages.for_each(&mut|relative,views|{shared::checked(b,poll)?;if !selected(relative){return Ok(true)}let file=views.source_file()?;if file.rel!=relative{return Err("Appearance schema original relative path differs".into())}let regs=policy::registrations_of(file);let events=policy::watch_events_of(file);fund(b,regs_bound(&regs))?;fund(b,events_bound(&events))?;let regs_copy=regs.clone();let events_copy=events.clone();if regs_copy.capacity()>regs.len().saturating_mul(4)||events_copy.capacity()>events.len().saturating_mul(4){b.deny();return Err(Failure::Operational(io::ErrorKind::OutOfMemory.into()))}shared::row(b,poll,&mut schema)?;schema.push((shared::own(b,poll,relative)?,regs_copy,events_copy));shared::checked(views.allocation_budget(root),poll)?;Ok(true)})?{return Err("Appearance schema source stopped before EOF".into())}
fund(b,schema.len().checked_mul(4*std::mem::size_of::<(String,Vec<policy::RegFact>,Vec<policy::WatchEvent>)>()).and_then(|n|n.checked_add(128)))?;schema.sort_by(|a,b|a.0.cmp(&b.0));let mut regs=Vec::new();let mut events=Vec::new();shared::reserve_append(b,poll,&mut regs,schema.len())?;shared::reserve_append(b,poll,&mut events,schema.len())?;let mut context_peak=Some(4096usize);for(_,registration,event)in schema{shared::checked(b,poll)?;context_peak=context_peak.and_then(|n|n.checked_add(regs_bound(&registration)?)).and_then(|n|n.checked_add(events_bound(&event)?));regs.push(registration);events.push(event);}fund(b,context_peak.and_then(|n|n.checked_mul(2)))?;let context=policy::schema(index,&regs,&events);let mut owning=HashSet::new();
if !pages.for_each(&mut|relative,views|{shared::checked(b,poll)?;if !selected(relative){return Ok(true)}let file=views.source_file()?;if file.rel!=relative{return Err("Appearance owning original relative path differs".into())}for pair in policy::owning_file(&context,file){shared::checked(b,poll)?;if !owning.contains(&pair){fund(b,pair.0.len().checked_add(pair.1.len()).and_then(|n|n.checked_mul(4)).and_then(|n|n.checked_add(2048)))?;owning.try_reserve(1).map_err(|_|Failure::Operational(io::ErrorKind::OutOfMemory.into()))?;owning.insert((shared::own(b,poll,&pair.0)?,shared::own(b,poll,&pair.1)?));}}shared::checked(views.allocation_budget(root),poll)?;Ok(true)})?{return Err("Appearance owning source stopped before EOF".into())}
let mut files=Vec::new();if !pages.for_each(&mut|relative,views|{shared::checked(b,poll)?;if !selected(relative){return Ok(true)}let file=views.source_file()?;if file.rel!=relative{return Err("Appearance judge original relative path differs".into())}let raw=policy::judge_file(&context,&owning,file);views.allocation_budget(root).charge(raw.len().checked_mul(4*std::mem::size_of::<(&str,usize)>()).and_then(|n|n.checked_add(128)).ok_or("Appearance finding row overflow")?).map_err(|message|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))?;let found=raw.into_iter().map(|(rule,_,line)|(rule,line)).collect();let data=crate::captured_sys_fields_pages::record_rows(views,found,&["sys_update_icon"],&["update_icon_override"],root,poll)?;shared::row(b,poll,&mut files)?;files.push((shared::own(b,poll,relative)?,data));Ok(true)})?{return Err("Appearance judgement source stopped before EOF".into())}fund(b,files.len().checked_mul(4*std::mem::size_of::<(String,shared::ApiData)>()).and_then(|n|n.checked_add(128)))?;files.sort_by(|a,b|a.0.cmp(&b.0));let mut data=shared::empty();for(_,file)in files{shared::checked(b,poll)?;shared::append(&mut data,file,root,poll)?;}drop(owning);drop(context);drop(regs);drop(events);Ok(AppearanceData{data})})}
